use crate::{Error, ManagementSession};
use secrecy::{ExposeSecretMut, SecretBox};

/// Generated bytes with redacted Debug and zeroization on drop, including failures.
pub type RandomBytes = SecretBox<Vec<u8>>;

/// Bounded token-random request. No seed or software fallback is supplied.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct RandomRequest {
    length: usize,
}
impl RandomRequest {
    /// Maximum bytes per request: one MiB.
    pub const MAXIMUM: usize = 1024 * 1024;
    /// Reject empty or oversized requests before allocation or token calls.
    pub fn new(length: usize) -> Result<Self, Error> {
        if length == 0 || length > Self::MAXIMUM {
            return Err(Error::InvalidRandomLength);
        }
        Ok(Self { length })
    }
    /// Exact requested output length in bytes.
    pub fn length(self) -> usize {
        self.length
    }
}
impl ManagementSession<'_> {
    /// Generate once using the session's token, with no automatic authentication or retry.
    /// The provider may require login even when RNG capability is advertised.
    pub fn generate_random(&mut self, request: RandomRequest) -> Result<RandomBytes, Error> {
        let mut bytes = SecretBox::new(Box::new(vec![0; request.length()]));
        self.session.generate_random(bytes.expose_secret_mut())?;
        Ok(bytes)
    }
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn random_requests_are_bounded_and_output_debug_is_redacted() {
        for length in [0, RandomRequest::MAXIMUM + 1, usize::MAX] {
            assert!(matches!(
                RandomRequest::new(length),
                Err(Error::InvalidRandomLength)
            ));
        }
        assert_eq!(RandomRequest::new(1).unwrap().length(), 1);
        assert_eq!(
            RandomRequest::new(RandomRequest::MAXIMUM).unwrap().length(),
            RandomRequest::MAXIMUM
        );
        let bytes = SecretBox::new(Box::new(b"random-redaction-canary".to_vec()));
        assert!(!format!("{bytes:?}").contains("canary"));
        assert!(format!("{bytes:?}").contains("REDACTED"));
    }
}
